#include <filesystem>
#include <iostream>

namespace fs = std::filesystem;

int main() {
  fs::path root = fs::temp_directory_path() / "atlas_dotdot_demo";
  fs::remove_all(root);
  fs::create_directories(root / "real" / "sub");
  fs::create_directory_symlink(root / "real" / "sub", root / "link");

  fs::path p = root / "link" / "..";
  std::cout << fs::equivalent(p, root / "real") << ' '
            << fs::equivalent(p.lexically_normal(), root / "real") << '\n';
  fs::remove_all(root);
}

